/**
 * Optional Effect filesystem for atomic publication. Callers default to real file
 * descriptors; Effect hosts can supply failure-producing implementations.
 * @since 1.0.0
 */
import * as Context from "effect/Context";
/** Optional host filesystem capability; undefined selects native file publication.
 * @since 1.0.0
 * @private
 */
export const PublicationFileSystem = Context.Reference("@smthrs/targets/internal/PublicationFileSystem", { defaultValue: () => undefined });

/**
 * An optional Effect process capability; callers default to the existing host adapter.
 * Keeping this reference internal lets fault services exercise pipe failures
 * while ordinary callers retain the real platform-node lifecycle and cleanup.
 * @since 1.0.0
 */
import * as Context from "effect/Context";
/** Optional host process capability; undefined selects the native adapter.
 * @since 1.0.0
 * @private
 */
export const Process = Context.Reference("@smthrs/targets/internal/Process", { defaultValue: () => undefined });

/**
 * The homepage a factory declares for its repository: `.smithers/home.json`.
 *
 * A repository's workspace chat opens with its homepage message, a README
 * alternative the maintainer declares in
 * `.smithers/FACTORY.ts` as `export const home = Smithers.Factory.Home({ blocks })`,
 * the second export beside the factory itself. Blocks are declared values,
 * never raw HTML, in the one home format `@smthrs/views` defines (`Home`),
 * which the app reads the file with. The app renders every block from data;
 * a string carrying an HTML tag is refused where it is written.
 *
 * The declaration is inert, like {@link Flow.Flow}. The `FactoryProjection`
 * target (`Factory.ts`) projects it into a checked-in JSON file beside
 * `.smithers/factory.json` the same way `ci.yml` and the root `tsconfig.json`
 * are projected: `write` renders it, `check` fails on drift, and the `lint`
 * verb never writes. The file is checked in so the public mirror serves it
 * signed out and a workspace without `node_modules` never has to evaluate
 * `FACTORY.ts`.
 *
 * @since 1.0.0
 */
import * as Result from "effect/Result";
import * as SchemaIssue from "effect/SchemaIssue";
import * as Views from "@smthrs/views";
import * as Schema from "effect/Schema";
import * as $platform from "./Home.platform.js";
/**
 * The home file's format, one copy: `@smthrs/views`' `Home`, which the app
 * reads the file with. Every constant, schema and block below is that
 * package's own, under the names this module has always exported.
 */
const Format = Views.Home;
/**
 * Maximum length of one block's title or one link's label (`Home.maximumTitleLength` of `@smthrs/views`).
 *
 * @category constants
 * @since 1.0.0
 */
export const maximumTitleLength = Format.maximumTitleLength;
/**
 * Maximum length of one text block (`Home.maximumTextLength` of `@smthrs/views`).
 *
 * @category constants
 * @since 1.0.0
 */
export const maximumTextLength = Format.maximumTextLength;
/**
 * Maximum length of one link URL (`Home.maximumUrlLength` of `@smthrs/views`).
 *
 * @category constants
 * @since 1.0.0
 */
export const maximumUrlLength = Format.maximumUrlLength;
/**
 * Maximum number of blocks one home declares (`Home.maximumBlocks` of `@smthrs/views`).
 *
 * @category constants
 * @since 1.0.0
 */
export const maximumBlocks = Format.maximumBlocks;
/**
 * The shape of raw HTML in a string (`Home.htmlPattern` of `@smthrs/views`): a
 * tag, a closing tag, a comment, or a processing instruction opener.
 *
 * @category constants
 * @since 1.0.0
 */
export const htmlPattern = Format.htmlPattern;
/**
 * A one-line title or label: non-empty, bounded, one line, no HTML.
 *
 * @category schemas
 * @since 1.0.0
 */
export const Title = Format.Title;
/**
 * A paragraph of plain text: non-empty, bounded, no HTML.
 *
 * @category schemas
 * @since 1.0.0
 */
export const Prose = Format.Prose;
/**
 * A link target: an absolute `http` or `https` URL.
 *
 * @category schemas
 * @since 1.0.0
 */
export const Url = Format.Url;
/**
 * A relative path that cannot escape the repository.
 *
 * @category schemas
 * @since 1.0.0
 */
export const RepositoryPath = Format.RepositoryPath;
/**
 * A slash leaf name or repository flow id (`Home.FlowName` of `@smthrs/views`).
 *
 * @category schemas
 * @since 1.0.0
 */
export const PromptFlow = Format.FlowName;
/**
 * A paragraph of plain text under an optional title.
 *
 * @category schemas
 * @since 1.0.0
 */
export const TextBlock = Format.TextBlock;
/**
 * One link: the label the app shows and the URL it opens.
 *
 * @category schemas
 * @since 1.0.0
 */
export const Link = Format.Link;
/**
 * A list of links under an optional title.
 *
 * @category schemas
 * @since 1.0.0
 */
export const LinksBlock = Format.LinksBlock;
/**
 * The repository's flows, which the app lists from its own catalog. The block carries no rows.
 *
 * @category schemas
 * @since 1.0.0
 */
export const FlowsBlock = Format.FlowsBlock;
/**
 * A prompt: a heading over the way to ask, and the flow that takes the question.
 *
 * @category schemas
 * @since 1.0.0
 */
export const PromptBlock = Format.PromptBlock;
/**
 * The pictures an app tile may wear: what the app's result looks like.
 *
 * @category schemas
 * @since 1.0.0
 */
export const AppPicture = Format.AppPicture;
/**
 * An app: one flow's button, with a title and a picture.
 *
 * @category schemas
 * @since 1.0.0
 */
export const AppBlock = Format.AppBlock;
/**
 * A repository markdown file, read at the home's own commit.
 *
 * @category schemas
 * @since 1.0.0
 */
export const MarkdownBlock = Format.MarkdownBlock;
/**
 * The repository's live stack of changes, which the app reads itself. The block carries no rows.
 *
 * @category schemas
 * @since 1.0.0
 */
export const StackBlock = Format.StackBlock;
/**
 * The view a repository flow declares (`Smithers.Flow({ view })`), drawn here
 * in its place: `Factory.Home({ blocks: [Smithers.Home.View({ flow })] })`.
 *
 * @category schemas
 * @since 1.0.0
 */
export const ViewBlock = Format.ViewBlock;
/**
 * One declared block: any kind `@smthrs/views` reads, the landing page's
 * (`hero`, `code`, `cards`, `stats`, `releases`) and the live ones (`issues`,
 * `runs`) included.
 *
 * @category schemas
 * @since 1.0.0
 */
export const Block = Format.Block;
/**
 * One block of a flow's own view: every block that needs no server
 * resolution. A markdown block reads a file at main, which only the
 * homepage route resolves, and a view block inside a view would recurse.
 *
 * @category schemas
 * @since 1.0.0
 */
export const FlowViewBlock = Schema.Union([TextBlock, LinksBlock, FlowsBlock, PromptBlock, StackBlock, AppBlock]);
/**
 * The view a flow declares: its blocks, in declaration order.
 *
 * @category schemas
 * @since 1.0.0
 */
export const FlowView = Schema.NonEmptyArray(FlowViewBlock).check(Schema.isMaxLength(maximumBlocks));
/**
 * The home declaration `.smithers/FACTORY.ts` exports as `home`.
 *
 * @category schemas
 * @since 1.0.0
 */
export const Declaration = Schema.TaggedStruct("HomeDeclaration", {
    blocks: Schema.NonEmptyArray(Block).check(Schema.isMaxLength(maximumBlocks))
});
/**
 * The document `.smithers/home.json` holds: the blocks, in declaration order.
 *
 * @category schemas
 * @since 1.0.0
 */
export const Document = Schema.Struct({
    blocks: Schema.Array(Block)
});
/**
 * Reports whether a value is a home declaration.
 *
 * @category guards
 * @since 1.0.0
 */
export const isHomeDeclaration = Schema.is(Declaration);
const formatIssue = SchemaIssue.makeFormatterDefault();
/**
 * Reads one constructor's options as a plain object of enumerable data
 * properties, exactly once, or throws the reason it is not one. Shared with
 * the factory declaration in `Factory.ts`, so every declaration constructor
 * refuses the same shapes with the same words.
 *
 * @category validation
 * @since 1.0.0
 */
export const plainOptions = (name, options, keys) => $platform.plainOptions(name, options, keys);
/**
 * Decodes a value through a schema or throws a `TypeError` naming the
 * constructor and the first issue.
 *
 * @category validation
 * @since 1.0.0
 */
export const decode = (name, schema, value) => {
    const result = Schema.decodeUnknownResult(schema)(value);
    if (Result.isFailure(result))
        throw new TypeError(`${name}: ${formatIssue(result.failure.issue)}`);
    return result.success;
};
/**
 * Freezes a value and every nested object it holds, so a declaration never
 * changes after it is written.
 *
 * @category validation
 * @since 1.0.0
 */
export const freezeDeep = (value) => {
    if (typeof value === "object" && value !== null) {
        for (const nested of Object.values(value))
            freezeDeep(nested);
        Object.freeze(value);
    }
    return value;
};
/**
 * Declares a paragraph of plain text.
 *
 * @category constructors
 * @since 1.0.0
 */
export const Text = (options) => freezeDeep(decode("Home.Text", TextBlock, {
    type: "text",
    ...plainOptions("Home.Text", options, new Set(["title", "text"]))
}));
/**
 * Declares a list of links.
 *
 * @category constructors
 * @since 1.0.0
 */
export const Links = (options) => freezeDeep(decode("Home.Links", LinksBlock, {
    type: "links",
    ...plainOptions("Home.Links", options, new Set(["title", "links"]))
}));
/**
 * Declares the featured-flows block.
 *
 * @category constructors
 * @since 1.0.0
 */
export const Flows = (options = {}) => freezeDeep(decode("Home.Flows", FlowsBlock, {
    type: "flows",
    ...plainOptions("Home.Flows", options, new Set(["title"]))
}));
/**
 * Declares the homepage prompt.
 *
 * @category constructors
 * @since 1.0.0
 */
export const Prompt = (options = {}) => freezeDeep(decode("Home.Prompt", PromptBlock, {
    type: "prompt",
    ...plainOptions("Home.Prompt", options, new Set(["flow", "title", "placeholder"]))
}));
/**
 * Declares an app: a flow presented as a picture tile on the home.
 *
 * @category constructors
 * @since 1.0.0
 */
export const App = (options) => freezeDeep(decode("Home.App", AppBlock, {
    type: "app",
    ...plainOptions("Home.App", options, new Set(["flow", "title", "picture"]))
}));
/**
 * Declares a markdown file inside this repository.
 *
 * @category constructors
 * @since 1.0.0
 */
export const Markdown = (options) => freezeDeep(decode("Home.Markdown", MarkdownBlock, {
    type: "markdown",
    ...plainOptions("Home.Markdown", options, new Set(["path", "title"]))
}));
/**
 * Declares the repository's live mythical stack.
 *
 * @category constructors
 * @since 1.0.0
 */
export const Stack = (options = {}) => freezeDeep(decode("Home.Stack", StackBlock, {
    type: "stack",
    ...plainOptions("Home.Stack", options, new Set(["title"]))
}));
/**
 * Draws a repository flow's declared view in this place.
 *
 * @category constructors
 * @since 1.0.0
 */
export const View = (options) => freezeDeep(decode("Home.View", ViewBlock, {
    type: "view",
    ...plainOptions("Home.View", options, new Set(["flow"]))
}));
/**
 * Declares the repository's homepage from declared blocks.
 *
 * Every block has to be a value one of the block constructors returned, or
 * an equal plain value; a string, an element, or any other shape is refused
 * with the block index in the message.
 *
 * @example
 * ```ts
 * import { Smithers } from "@smthrs/targets"
 *
 * export const home = Smithers.Factory.Home({
 *   blocks: [
 *     Smithers.Home.Text({ text: "Smithers builds itself with Smithers." }),
 *     Smithers.Home.Flows({ title: "Try first" }),
 *     Smithers.Home.Markdown({ path: "README.md" })
 *   ]
 * })
 * ```
 *
 * @category constructors
 * @since 1.0.0
 */
export const Home = (options) => {
    const plain = plainOptions("Factory.Home", options, new Set(["blocks"]));
    const blocks = plain["blocks"];
    if (!Array.isArray(blocks))
        throw new TypeError("Factory.Home blocks must be an array of declared blocks");
    blocks.forEach((block, index) => {
        if (typeof block !== "object" || block === null) {
            throw new TypeError(`Factory.Home block ${index} must be a declared block (Smithers.Home.Text, Links, Flows, Prompt, Markdown, Stack, App, View), not ${typeof block === "string" ? "a string" : typeof block}`);
        }
    });
    return freezeDeep(decode("Factory.Home", Declaration, { _tag: "HomeDeclaration", blocks }));
};
/**
 * Renders the projected document: two-space indentation and a trailing
 * newline, so the checked-in file diffs like a hand-written one.
 *
 * @category rendering
 * @since 1.0.0
 */
export const render = (declaration) => `${JSON.stringify(Schema.encodeSync(Document)({ blocks: declaration.blocks }), null, 2)}\n`;
/**
 * Reads a rendered document back, or reports why the text is not one.
 *
 * @category parsing
 * @since 1.0.0
 */
export const parse = (text) => {
    let value;
    try {
        value = JSON.parse(text);
    }
    catch (cause) {
        return `the homepage is not JSON: ${cause instanceof Error ? cause.message : String(cause)}`;
    }
    const result = Schema.decodeUnknownResult(Document)(value);
    return Result.isFailure(result)
        ? `the homepage does not have the .smithers/home.json shape: ${formatIssue(result.failure.issue)}`
        : result.success;
};

import * as Schema from "effect/Schema";
import * as NodeUtil from "node:util/types";
import * as Home from "./Home.js";
import * as Target from "./Target.js";
/**
 * Maximum length of one declared flow id.
 *
 * @category constants
 * @since 1.0.0
 */
export const maximumIdLength = 256;
/**
 * The shape of a discovered flow id: path segments of letters, digits, `-`,
 * `_`, and `.`, joined by `/`, exactly as discovery derives them from the
 * directory path below `flows/`.
 *
 * @category constants
 * @since 1.0.0
 */
export const idPattern = /^(?!\.\.?(?:\/|$))[A-Za-z0-9_.-]+(?:\/(?!\.\.?(?:\/|$))[A-Za-z0-9_.-]+)*$/;
/**
 * Schema for one inert flow declaration.
 *
 * `summary` is absent rather than empty when a declaration carries none, and
 * `featured` is always present, so a catalog row never has to guess at a
 * default the declaration did not state.
 *
 * @category schemas
 * @since 1.0.0
 */
export const Declaration = Schema.TaggedStruct("FlowDeclaration", {
    /** The flow id, the directory path below `flows/`. */
    flow: Schema.NonEmptyString.check(Schema.isMaxLength(maximumIdLength), Schema.isPattern(idPattern)),
    /** The one-line summary a listing shows under the id. */
    summary: Schema.optional(Schema.NonEmptyString),
    /** Whether the repository recommends this flow first. */
    featured: Schema.Boolean,
    /** The view the flow draws: on the run's monitor, and as the repository's default view when the home names it. */
    view: Schema.optional(Home.FlowView)
});
const optionKeys = new Set(["flow", "summary", "featured", "view"]);
/**
 * Declares how the repository presents one of its flows.
 *
 * The declaration is validated where it is written: the id has to be a
 * discovery-shaped path, the summary one non-empty line, and `featured` a
 * boolean. Whether the id names a flow that exists is decided when the
 * catalog is rendered, because only discovery knows.
 *
 * @example
 * ```ts
 * import { Smithers } from "@smthrs/targets"
 *
 * export const review = Smithers.Flow({
 *   flow: "review",
 *   summary: "Review the working-copy change and return a verdict with reasons.",
 *   featured: true
 * })
 * ```
 *
 * @category constructors
 * @since 1.0.0
 */
export const Flow = (options) => {
    if (typeof options !== "object" || options === null || Array.isArray(options) || NodeUtil.isProxy(options) ||
        (Object.getPrototypeOf(options) !== Object.prototype && Object.getPrototypeOf(options) !== null))
        throw new TypeError("Flow options must be a plain object");
    if (Object.getOwnPropertySymbols(options).length > 0) {
        throw new TypeError("Flow options must not contain symbol properties");
    }
    const plain = {};
    for (const key of Object.getOwnPropertyNames(options)) {
        if (!optionKeys.has(key))
            throw new TypeError(`Flow received unknown option ${JSON.stringify(key)}`);
        const descriptor = Object.getOwnPropertyDescriptor(options, key);
        if (!("value" in descriptor) || descriptor.enumerable !== true) {
            throw new TypeError(`Flow option ${key} must be an enumerable data property`);
        }
        plain[key] = descriptor.value;
    }
    const split = Target.splitPresentation(plain);
    if (typeof split === "string")
        throw new TypeError(`Flow ${JSON.stringify(plain["flow"])}: ${split}`);
    const flow = split.attrs["flow"];
    if (typeof flow !== "string" || !flow.isWellFormed())
        throw new TypeError("Flow id must be a well-formed string");
    if (flow.length > maximumIdLength || !idPattern.test(flow)) {
        throw new TypeError(`Flow id must be a directory path below flows/ (segments of letters, digits, "-", "_", "."): ${JSON.stringify(flow)}`);
    }
    const view = split.attrs["view"];
    return Home.freezeDeep(Declaration.make({
        flow,
        ...(split.presentation.summary === undefined ? {} : { summary: split.presentation.summary }),
        featured: split.presentation.featured,
        ...(view === undefined ? {} : { view: Home.decode(`Flow ${JSON.stringify(flow)} view`, Home.FlowView, view) })
    }));
};

/**
 * The flow catalog: discovered flows joined with their declarations.
 *
 * A repository's flows are discovered from `flows/` by the registry, and how
 * the repository presents them is declared in `.smithers/FACTORY.ts` with
 * {@link Flow.Flow} under the factory's `flows` key. Neither side alone is a
 * listing a reader can trust without running discovery: the Worker that
 * serves smithers.sh reads the public mirror and imports nothing, and a
 * workspace without `node_modules` cannot evaluate `FACTORY.ts`. The
 * `FactoryProjection` target (`Factory.ts`) projects both into the `flows`
 * rows of the checked-in `.smithers/factory.json`.
 *
 * This module is the pure half: the shape of a catalog row and the rules
 * that order the rows, testable without a filesystem. The discovery runs in
 * the executor, which hands {@link rows} the discovered flows.
 *
 * @since 1.0.0
 */
import * as Schema from "effect/Schema";
import * as Home from "./Home.js";
/**
 * The entry file a flow was discovered from: a `flow.ts` module, a
 * `flow.mdx` prompt, or a foreign `SKILL.md`.
 *
 * @category schemas
 * @since 1.0.0
 */
export const Kind = Schema.Literals(["ts", "mdx", "skill"]);
/**
 * One flow as discovery reports it, reduced to what the catalog carries.
 *
 * `path` is workspace-relative and POSIX, so the same file renders the same
 * row on every host.
 *
 * @category schemas
 * @since 1.0.0
 */
export const DiscoveredFlow = Schema.Struct({
    id: Schema.NonEmptyString,
    description: Schema.String,
    kind: Kind,
    path: Schema.NonEmptyString,
    capabilities: Schema.Array(Schema.String),
    model: Schema.NullOr(Schema.Union([Schema.String, Schema.NonEmptyArray(Schema.String)])),
    modelInvocable: Schema.Boolean,
    inputSchema: Schema.optional(Schema.Json),
    flows: Schema.optional(Schema.Array(Schema.String)),
    budget: Schema.optional(Schema.Json),
    view: Schema.optional(Home.FlowView)
});
/**
 * One catalog row: the discovered flow joined with its declaration.
 *
 * `summary` is `null` and `featured` is `false` for a flow no declaration
 * names, so a consumer reads every row the same way.
 *
 * `view` is the view the flow DRAWS, and it has to be on the row: the row is
 * what `Factory.renderProjection` encodes into `.smithers/factory.json`, and
 * the projection is the only place the app reads a repository's flows from
 * (`@smthrs/rpc/FactoryProjection` `FactoryFlowSchema`, the app's
 * `RepositoryFlowsSeam`). A field the row omits is dropped on encode, so the
 * monitor's custom view and a homepage that names the flow owning the landing
 * both read "declares no view" however the repository declared it (#4025).
 * It is the same `Home.FlowView` the declaration carries, so there is one
 * declaration and one view vocabulary end to end.
 *
 * @category schemas
 * @since 1.0.0
 */
export const Row = Schema.Struct({
    id: Schema.NonEmptyString,
    description: Schema.String,
    summary: Schema.NullOr(Schema.String),
    featured: Schema.Boolean,
    kind: Kind,
    path: Schema.NonEmptyString,
    capabilities: Schema.Array(Schema.String),
    model: DiscoveredFlow.fields.model,
    modelInvocable: Schema.Boolean,
    inputSchema: Schema.optional(Schema.Json),
    flows: Schema.optional(Schema.Array(Schema.String)),
    budget: Schema.optional(Schema.Json),
    view: Schema.optional(Home.FlowView)
});
/**
 * The catalog could not be joined: a declaration names no discovered flow,
 * two declarations name one flow, or the flows directory could not be read.
 *
 * @category errors
 * @since 1.0.0
 */
export class FlowCatalogError extends Schema.TaggedError()("smithers-build/FlowCatalogError", {
    message: Schema.NonEmptyString
}) {
}
/**
 * Joins the discovered flows with the declarations into catalog rows.
 *
 * Rows are ordered featured first, in declaration order; then the remaining
 * declared flows, in declaration order; then every other discovered flow by
 * id. A declaration that names no discovered flow, or a flow two declarations
 * name, is a failure carrying the id: a recommendation for a flow that does
 * not exist must never be written.
 *
 * @category constructors
 * @since 1.0.0
 */
export const rows = (discovered, declarations) => {
    const byId = new Map();
    for (const flow of discovered) {
        if (byId.has(flow.id)) {
            throw new FlowCatalogError({ message: `discovery reported the flow ${JSON.stringify(flow.id)} twice` });
        }
        byId.set(flow.id, flow);
    }
    const declared = new Map();
    const unknown = [];
    for (const declaration of declarations) {
        if (declared.has(declaration.flow)) {
            throw new FlowCatalogError({
                message: `FACTORY.ts declares the flow ${JSON.stringify(declaration.flow)} twice`
            });
        }
        declared.set(declaration.flow, declaration);
        if (!byId.has(declaration.flow))
            unknown.push(declaration.flow);
    }
    if (unknown.length > 0) {
        throw new FlowCatalogError({
            message: `FACTORY.ts declares ${unknown.length === 1 ? "a flow" : "flows"} discovery did not find: ${unknown.map((id) => JSON.stringify(id)).join(", ")}`
        });
    }
    const row = (flow, declaration) => ({
        id: flow.id,
        description: flow.description,
        summary: declaration?.summary ?? null,
        featured: declaration?.featured ?? false,
        kind: flow.kind,
        path: flow.path,
        capabilities: flow.capabilities,
        model: flow.model,
        modelInvocable: flow.modelInvocable,
        ...(flow.flows === undefined ? {} : { flows: flow.flows }),
        ...(flow.budget === undefined ? {} : { budget: flow.budget }),
        ...(flow.inputSchema === undefined ? {} : { inputSchema: flow.inputSchema }),
        /*
         * One view reaches the catalog from either side of the join: the
         * repository's declaration for the flow (`Smithers.Flow({ view })`) is
         * the authority, and a flow that carries its own view is used where the
         * declaration names none. A flow no declaration names keeps its own.
         */
        ...((declaration?.view ?? flow.view) === undefined ? {} : { view: declaration?.view ?? flow.view })
    });
    const featured = [];
    const declaredOnly = [];
    for (const declaration of declared.values()) {
        const built = row(byId.get(declaration.flow), declaration);
        if (declaration.featured)
            featured.push(built);
        else
            declaredOnly.push(built);
    }
    const rest = [...byId.values()]
        .filter((flow) => !declared.has(flow.id))
        .sort((left, right) => left.id < right.id ? -1 : left.id > right.id ? 1 : 0)
        .map((flow) => row(flow, undefined));
    return [...featured, ...declaredOnly, ...rest];
};

/**
 * Inert mise version-authority declarations and tool references.
 *
 * mise is the version pin authority for every toolchain layer in a
 * multi-language workspace: the `[tools]` table of the declared
 * `.mise.toml`/`mise.toml` keys the tools a target uses, so bumping one pin
 * invalidates exactly the targets keyed on that tool. This module declares
 * the config as a workspace toolchain layer and the `bin` reference a
 * target uses to name one config-pinned executable; resolution and the
 * typed host refusal when mise is absent live in the planner.
 *
 * @since 0.1.0
 */
import * as Schema from "effect/Schema";
import * as Input from "./Input.js";
import * as Reference from "./Reference.js";
/**
 * A mise config participating in the workspace toolchain layer list.
 *
 * @category declarations
 * @since 0.1.0
 */
export const Declaration = Schema.TaggedStruct("Mise", {
    config: Input.File
});
/**
 * Checks whether a value is an `S.Mise` declaration.
 *
 * @category guards
 * @since 0.1.0
 */
export const isDeclaration = Schema.is(Declaration);
const make = (options) => {
    if (typeof options !== "object" || options === null)
        throw new TypeError("Mise options must be an object");
    for (const key of Object.getOwnPropertyNames(options)) {
        if (key !== "config")
            throw new TypeError(`Mise received unknown option ${JSON.stringify(key)}`);
    }
